  events=[json.loads(l) for l in (p/'model_trace.jsonl').read_text().splitlines()];gens={e['candidate_checkpoint_id']:e['raw_generation'] for e in events if e['type']=='model_session_generation_returned'};starts={e['request_id']:e for e in events if e['type']=='model_session_generation_started'}
