  for e in events:
   if e['type']!='model_session_generation_returned':continue
   raw=e['raw_generation'];start=starts[e['request_id']];cp=s.model_states[start['input_checkpoint_id']];chain=[];visited=set()
   while cp:
    assert cp.checkpoint_id not in visited;visited.add(cp.checkpoint_id);chain.append(cp);cp=s.model_states.get(cp.parent_checkpoint_id)
   assert chain[-1].transcript==bootstrap;ids=[];seen=set()
   for cp in reversed(chain):
    assert cp.state_profile_id==profile['id'] and cp.state_profile_sha256==profile['sha256'];assert cp.native_state_metadata['model_sha256']==reg['model_sha256']
    if cp.parent_checkpoint_id:assert cp.native_state_metadata['cache_binding']['parent_state_digest']==s.model_states[cp.parent_checkpoint_id].native_state_digest
    if cp.checkpoint_id in gens:ids.extend(gens[cp.checkpoint_id]['raw_token_ids'])
