     ids.extend(tokenizer().encode(cp.transcript))
   assert raw['prompt_token_ids']==[0]+ids and raw['input_bos_token_count']==1
   assert start['input_digest']==s.model_states[start['input_checkpoint_id']].native_state_digest
   text=tokenizer().decode(ids);(p/'actual_inputs').mkdir(exist_ok=True);(p/'actual_inputs'/f"{e['request_id']}.txt").write_text(text);consumed.update(seen)
   if raw.get('candidate_id') in committed and result['final'] is not None:
    try:command=parse_model_command(raw['raw_output'])
