   calls.append({'request_id':e['request_id'],'input_tokens':len(raw['prompt_token_ids']),'output_tokens':len(raw['raw_token_ids']),'input_sha256':hashlib.sha256(text.encode()).hexdigest(),'input_checkpoint':start['input_checkpoint_id'],'candidate_checkpoint':e['candidate_checkpoint_id'],'finish':raw['finish_reason'],'events':sorted(seen),'raw_output':raw['raw_output']})
  observations=[]
  for action in result['actions']:
   eid='EV-ACTION-'+action['action_id'];event=s.model_events.get(eid);item={'action_id':action['action_id'],'operation':action['action_type'],'success':action['result']['success'],'consumed':eid in consumed,'consumed_by_answer':eid in answer_events}
   if action['action_type']=='read_file' and action['result']['success']:
    content=(root/'workspace'/action['arguments']['path']).read_bytes();chunk=action['result']['metadata']['chunk'];assert action['result']['output'].encode()==content[chunk['byte_start']:chunk['byte_end']];item.update(path=action['arguments']['path'],byte_start=chunk['byte_start'],byte_end=chunk['byte_end'],file_bytes=len(content));item['complete_file']=chunk['byte_start']==0 and chunk['byte_end']==len(content)
    assert event is not None;obs=event.payload['result']['observation'];assert obs['projection_complete'] and ''.join(span['content'] for span in obs['exact_spans'])==action['result']['output']
   observations.append(item)
  rows.append({'id':root.name,'arm':arm,'termination':result['termination'],'final':result['final'],'protocol_rejections':result['protocol_rejections'],'calls':calls,'observations':observations,'passed_mechanical_audit':True,'interpretation':'exact declared profile/input/parent lineage, not a new independent tensor equivalence measurement'})
 (D/phase/'MECHANICAL_AUDIT.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n');print(phase,len(rows),sum(len(r['calls']) for r in rows))
