  try:
   payload={'actual_rwkv_input':e['input_text'],'original_output':e['raw_generation']['raw_output']};save(folder/'TARGET_REQUEST.json',payload)
   proposed=request(client,'state_tune_target',s['id'],payload,SYSTEM,SCHEMA);save(folder/'TARGET_RESPONSE.json',proposed);assert len(proposed['candidates'])==5;seen=set()
   for i,text in enumerate(proposed['candidates']):
    cid=s['id']+f'-v{i+1}';dest=folder/f'v{i+1}';dest.mkdir();row={'id':cid,'seed_id':s['id'],'candidate':text,'accepted_by_api':False,'error':None,'input_sha256':digest(e['input_text']),'augmentation':'alternate target at same actual production boundary'}
    try:
     json.loads(text);cmd=parse_model_command(text);assert cmd.name=='final_answer' and set(cmd.arguments)=={'text'}
     canonical=json.dumps(cmd.to_wire_dict(),ensure_ascii=False,sort_keys=True);assert canonical not in seen,'duplicate target';seen.add(canonical)
     target=text+JSON_CALL_STOP_SUFFIXES[0];ids=tokenizer().encode(target);assert len(ids)<=1800 and len(ids)+len(e['input_token_ids'])-1<=8192,'target exceeds frozen budget'
     row.update(target_text=target,target_sha256=digest(target),target_tokens=len(ids))
