     review=request(client,'state_tune_target_review',cid,payload,REVIEW,RS);save(dest/'REVIEW_RESPONSE.json',review);assert type(review['accepted']) is bool
     row.update(accepted_by_api=review['accepted'],review_issues=review['issues'])
    except Exception as ex:row['error']=type(ex).__name__+': '+str(ex)
    save(dest/'RESULT.json',row);rows.append(row)
  except Exception as ex:save(folder/'ERROR.json',{'error':type(ex).__name__+': '+str(ex)})
  finally:client.close();save(folder/'RESULTS.json',rows);print(s['id'],len(rows),sum(r['accepted_by_api'] for r in rows),flush=True)
  return rows
 with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
  rows=[r for group in pool.map(one,reg['boundaries']) for r in group]
